/* 1.54 inch ST7789 240x240 on SPI2 bus*/

SPI_TypeDef *portLCD = SPI2;

u16 all_color[] = {BLACK, RED, GREEN, BLUE, MAGENTA, CYAN, YELLOW, WHITE};

const FontDef *bigFont = &Font_16x26;
const FontDef *midFont = &Font_11x18;
const FontDef *smalFont = &Font_8x8;
const FontDef *litlFont = &Font_7x10;

//------------------------------------------------------------------
void LCD_Write_Bus(u8 dat) 
{
	LCD_CS_Clr();
#if defined(SPI_GPIO)

	for (u8 i = 0; i < 8; i++) {			  
		LCD_SCLK_Clr();
		if (dat & 0x80) {
		   LCD_MOSI_Set();
		} else {
		   LCD_MOSI_Clr();
		}
		LCD_SCLK_Set();
		dat <<= 1;
	}
	
#elif defined(SPI_HW)
    
    while (SPI_I2S_GetFlagStatus(portLCD, SPI_I2S_FLAG_TXE) == RESET);
	SPI_I2S_SendData(portLCD, dat);
    //Delay_MS(1);//
	Delay_Us(1);

#endif
	LCD_CS_Set();
}
//------------------------------------------------------------------
void LCD_WR_DATA8(u8 dat)
{
	LCD_Write_Bus(dat);
}
//------------------------------------------------------------------
void LCD_WR_DATAS(u8 *dat, int len)
{

	//LCD_Writ_Bus(dat);
	for (int i = 0; i < len; i++) {
		while (SPI_I2S_GetFlagStatus(portLCD, SPI_I2S_FLAG_TXE) == RESET);
		SPI_I2S_SendData(portLCD, *dat++);
	}
}
//------------------------------------------------------------------
void LCD_WR_DATA(u16 dat)
{
	LCD_Write_Bus(dat >> 8);
	LCD_Write_Bus(dat);
}
//------------------------------------------------------------------
void LCD_WR_REG(u8 dat)
{
	LCD_DC_Clr();
	LCD_Write_Bus(dat);
	LCD_DC_Set();
}
//------------------------------------------------------------------
void LCD_Address_Set(u16 x1, u16 y1, u16 x2, u16 y2)
{
	if (!USE_HORIZONTAL) {
		LCD_WR_REG(0x2a);//ÁÐµØÖ·ÉèÖÃ
		LCD_WR_DATA(x1);
		LCD_WR_DATA(x2);
		LCD_WR_REG(0x2b);//ÐÐµØÖ·ÉèÖÃ
		LCD_WR_DATA(y1);
		LCD_WR_DATA(y2);
		LCD_WR_REG(0x2c);//´¢´æÆ÷Ð´
	} else if (USE_HORIZONTAL == 1) {
		LCD_WR_REG(0x2a);//ÁÐµØÖ·ÉèÖÃ
		LCD_WR_DATA(x1);
		LCD_WR_DATA(x2);
		LCD_WR_REG(0x2b);//ÐÐµØÖ·ÉèÖÃ
		LCD_WR_DATA(y1 + 80);
		LCD_WR_DATA(y2 + 80);
		LCD_WR_REG(0x2c);//´¢´æÆ÷Ð´
	} else if (USE_HORIZONTAL == 2) {
		LCD_WR_REG(0x2a);//ÁÐµØÖ·ÉèÖÃ
		LCD_WR_DATA(x1);
		LCD_WR_DATA(x2);
		LCD_WR_REG(0x2b);//ÐÐµØÖ·ÉèÖÃ
		LCD_WR_DATA(y1);
		LCD_WR_DATA(y2);
		LCD_WR_REG(0x2c);//´¢´æÆ÷Ð´
	} else {
		LCD_WR_REG(0x2a);//ÁÐµØÖ·ÉèÖÃ
		LCD_WR_DATA(x1 + 80);
		LCD_WR_DATA(x2 + 80);
		LCD_WR_REG(0x2b);//ÐÐµØÖ·ÉèÖÃ
		LCD_WR_DATA(y1);
		LCD_WR_DATA(y2);
		LCD_WR_REG(0x2c);//´¢´æÆ÷Ð´
	}
}
//------------------------------------------------------------------
int lcd_gpio_init()
{
#if defined(SPI_GPIO)
    GPIO_InitTypeDef GPIO_InitStructure = {0};

    RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOB, ENABLE);

    GPIO_InitStructure.GPIO_Pin = GPIO_Pin_9 | GPIO_Pin_10 | GPIO_Pin_11 | GPIO_Pin_12 | GPIO_Pin_13 | GPIO_Pin_15;
    GPIO_InitStructure.GPIO_Mode = GPIO_Mode_Out_PP;
    GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;
    GPIO_Init(GPIOB, &GPIO_InitStructure);

#elif defined(SPI_HW)
    GPIO_InitTypeDef GPIO_InitStructure = {0};
    SPI_InitTypeDef  SPI_InitStructure = {0};

    RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOB, ENABLE);
    RCC_APB1PeriphClockCmd(RCC_APB1Periph_SPI2, ENABLE);

    /* DC (PB10) & RESET (PB11) & CS (PB12) */
    GPIO_InitStructure.GPIO_Pin = GPIO_Pin_10 | GPIO_Pin_11 | GPIO_Pin_12;
    GPIO_InitStructure.GPIO_Mode = GPIO_Mode_Out_PP;
    GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;
    GPIO_Init(GPIOB, &GPIO_InitStructure);
    //GPIO_SetBits(GPIOA, GPIO_Pin_2);

    /* SPI_CLK */
    GPIO_InitStructure.GPIO_Pin = GPIO_Pin_13;
    GPIO_InitStructure.GPIO_Mode = GPIO_Mode_AF_PP;
    GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;
    GPIO_Init(GPIOB, &GPIO_InitStructure);

    /* SPI_MISO */
    GPIO_InitStructure.GPIO_Pin = GPIO_Pin_14;
    GPIO_InitStructure.GPIO_Mode = GPIO_Mode_IN_FLOATING;
    GPIO_Init(GPIOB, &GPIO_InitStructure);

    /* SPI_MOSI */
    GPIO_InitStructure.GPIO_Pin = GPIO_Pin_15;
    GPIO_InitStructure.GPIO_Mode = GPIO_Mode_AF_PP;
    GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;
    GPIO_Init(GPIOB, &GPIO_InitStructure);

    SPI_InitStructure.SPI_Direction = SPI_Direction_1Line_Tx;
    SPI_InitStructure.SPI_Mode = SPI_Mode_Master;
    SPI_InitStructure.SPI_DataSize = SPI_DataSize_8b;
    SPI_InitStructure.SPI_CPOL = SPI_CPOL_High;
    SPI_InitStructure.SPI_CPHA = SPI_CPHA_2Edge;
    SPI_InitStructure.SPI_NSS = SPI_NSS_Soft;
    SPI_InitStructure.SPI_BaudRatePrescaler = SPI_BaudRatePrescaler_2; /* APB1_CLK (72MHz) */
    SPI_InitStructure.SPI_FirstBit = SPI_FirstBit_MSB;
    SPI_InitStructure.SPI_CRCPolynomial = 7;
    SPI_Init(portLCD, &SPI_InitStructure);

    SPI_Cmd(portLCD, ENABLE);
#endif

    return 0;
}
//------------------------------------------------------------------
void LCD_Fill_Slow(u16 xsta, u16 ysta, u16 xend, u16 yend, u16 color)
{
	LCD_Address_Set(xsta, ysta, xend - 1, yend - 1);
	for (u16 i = ysta; i < yend; i++) {
		for (u16 j = xsta; j < xend; j++) {
			LCD_WR_DATA(color);
		}
	}
}
//---------------------------------------------------------------------------
void LCD_Fill_Fast(u16 xsta, u16 ysta, u16 xend, u16 yend, u16 color)
{
	LCD_Address_Set(xsta, ysta, xend - 1, yend - 1);

	LCD_CS_Clr();

	for (u16 i = ysta; i < yend; i++) {
		for (u16 j = xsta; j < xend; j++) {
            while(SPI_I2S_GetFlagStatus(portLCD, SPI_I2S_FLAG_TXE) == RESET);
            SPI_I2S_SendData(portLCD, color >> 8);
 
            while(SPI_I2S_GetFlagStatus(portLCD, SPI_I2S_FLAG_TXE) == RESET);
            SPI_I2S_SendData(portLCD, color);
		}
	}

	LCD_CS_Set();
}
//------------------------------------------------------------------
void LCD_Clr(uint16_t color)
{
	LCD_Address_Set(0, 0, LCD_W - 1, LCD_H - 1);

	LCD_CS_Clr();

	for (u16 i = 0; i < LCD_H; i++) {
		for (u16 j = 0; j < LCD_W; j++) {
            while(SPI_I2S_GetFlagStatus(portLCD, SPI_I2S_FLAG_TXE) == RESET);
            SPI_I2S_SendData(portLCD, color >> 8);
 
            while(SPI_I2S_GetFlagStatus(portLCD, SPI_I2S_FLAG_TXE) == RESET);
            SPI_I2S_SendData(portLCD, color);
		}
	}

	LCD_CS_Set();
}
//------------------------------------------------------------------
void LCD_DrawPixel(uint16_t x, uint16_t y, uint16_t color)
{
	if ((x >= LCD_W) || (y >= LCD_H)) return;
	
	LCD_Address_Set(x, y, x, y);
	LCD_WR_DATA(color);
}
//------------------------------------------------------------------
void LCD_DrawPixel_4px(uint16_t x, uint16_t y, uint16_t color)
{
	if ((x >= LCD_W) || (y >= LCD_H))	return;

	for (u16 i = y - 2; i < y + 2; i++) {
		for (u16 j = x - 2; j < x + 2; j++) {
			LCD_DrawPixel(j, i, color);
		}
	}
}
//------------------------------------------------------------------
void LCD_DrawLine(uint16_t x0, uint16_t y0, uint16_t x1, uint16_t y1, uint16_t color)
{
uint16_t swap;
uint16_t steep = ABS(y1 - y0) > ABS(x1 - x0);

    if (steep) {
		swap = x0;
		x0 = y0;
		y0 = swap;

		swap = x1;
		x1 = y1;
		y1 = swap;
    }

    if (x0 > x1) {
		swap = x0;
		x0 = x1;
		x1 = swap;

		swap = y0;
		y0 = y1;
		y1 = swap;
    }

    int16_t dx, dy;
    dx = x1 - x0;
    dy = ABS(y1 - y0);

    int16_t err = dx / 2;
    int16_t ystep;

    if (y0 < y1) {
        ystep = 1;
    } else {
        ystep = -1;
    }

    for (; x0 <= x1; x0++) {
        if (steep) {
            LCD_DrawPixel(y0, x0, color);
        } else {
            LCD_DrawPixel(x0, y0, color);
        }
        err -= dy;
        if (err < 0) {
            y0 += ystep;
            err += dx;
        }
    }
}
//------------------------------------------------------------------
void LCD_DrawCircle(uint16_t x0, uint16_t y0, uint8_t r, uint16_t color)
{
	int16_t f = 1 - r;
	int16_t ddF_x = 1;
	int16_t ddF_y = -2 * r;
	int16_t x = 0;
	int16_t y = r;

	LCD_DrawPixel(x0, y0 + r, color);
	LCD_DrawPixel(x0, y0 - r, color);
	LCD_DrawPixel(x0 + r, y0, color);
	LCD_DrawPixel(x0 - r, y0, color);

	while (x < y) {
		if (f >= 0) {
			y--;
			ddF_y += 2;
			f += ddF_y;
		}
		x++;
		ddF_x += 2;
		f += ddF_x;

		LCD_DrawPixel(x0 + x, y0 + y, color);
		LCD_DrawPixel(x0 - x, y0 + y, color);
		LCD_DrawPixel(x0 + x, y0 - y, color);
		LCD_DrawPixel(x0 - x, y0 - y, color);

		LCD_DrawPixel(x0 + y, y0 + x, color);
		LCD_DrawPixel(x0 - y, y0 + x, color);
		LCD_DrawPixel(x0 + y, y0 - x, color);
		LCD_DrawPixel(x0 - y, y0 - x, color);
	}
}
//------------------------------------------------------------------
void LCD_DrawFilledCircle(int16_t x0, int16_t y0, int16_t r, uint16_t color)
{
	int16_t f = 1 - r;
	int16_t ddF_x = 1;
	int16_t ddF_y = -2 * r;
	int16_t x = 0;
	int16_t y = r;

	LCD_DrawPixel(x0, y0 + r, color);
	LCD_DrawPixel(x0, y0 - r, color);
	LCD_DrawPixel(x0 + r, y0, color);
	LCD_DrawPixel(x0 - r, y0, color);
	LCD_DrawLine(x0 - r, y0, x0 + r, y0, color);

	while (x < y) {
		if (f >= 0) {
			y--;
			ddF_y += 2;
			f += ddF_y;
		}
		x++;
		ddF_x += 2;
		f += ddF_x;

		LCD_DrawLine(x0 - x, y0 + y, x0 + x, y0 + y, color);
		LCD_DrawLine(x0 + x, y0 - y, x0 - x, y0 - y, color);

		LCD_DrawLine(x0 + y, y0 + x, x0 - y, y0 + x, color);
		LCD_DrawLine(x0 + y, y0 - x, x0 - y, y0 - x, color);
	}
}
//------------------------------------------------------------------
char *mkLineCenter(char *str, uint16_t width)
{
char st[128] = {0};

	memset(st, 0x20, 127);
	int8_t k = strlen(str);
	if (k < width) {
		int8_t n = (width - k)/2;
		memcpy((char *)&st[n], (char *)str, k);
		st[k + n*2 + 1] = '\0';
		strcpy(str, st);
	}

	return str;
}
//------------------------------------------------------------------
void LCD_WriteChar(uint16_t x, uint16_t y, char ch, FontDef font, uint16_t color, uint16_t bgcolor)
{
uint32_t i, b, j;

	LCD_Address_Set(x, y, x + font.width - 1, y + font.height - 1);
	uint8_t cdata[] = {color >> 8, color & 0xFF};
	uint8_t bdata[] = {bgcolor >> 8, bgcolor & 0xFF};
	uint8_t *uk = NULL;

	LCD_CS_Clr();
	for (i = 0; i < font.height; i++) {
		b = font.data[(ch - 32) * font.height + i];
		for (j = 0; j < font.width; j++) {
			if ((b << j) & 0x8000) {
				uk = cdata;
			} else {
				uk = bdata;
			}
			LCD_WR_DATAS(uk, sizeof(cdata));
		}
	}
	LCD_CS_Set();
}
//-----------------------------------------------------------------------------------------
void LCD_WriteString(uint16_t x, uint16_t y, const char *str, FontDef font, uint16_t color, uint16_t bgcolor)
{
	if (!str) return;

	while (*str) {
		if (x + font.width >= LCD_W) {
			x = 0;
			y += font.height;
			if (y + font.height >= LCD_H) break;

			if (*str == ' ') {// skip spaces in the beginning of the new line
				str++;
				continue;
			}
		}
		if (*str != '\n') {
			LCD_WriteChar(x, y, *str, font, color, bgcolor);
			x += font.width;
		} else {
			x = 0;
			y += font.height;
		}
		str++;
	}
}
//------------------------------------------------------------------
void lcd_tick(u8 show, const u16 bk_color)
{
//u16 w = 8;
u16 h = 8;
u16 x = (LCD_W >> 1);// - (w >> 1);
u16 y = LCD_H - (h << 1);// - (h >> 1);

	if (bk_color != RED) y = h >> 1; 
	//LCD_Fill_Fast(x, y, x + w, y + h, show ? WHITE : bk_color);

	//LCD_DrawPixel_4px(x, y, show ? WHITE : bk_color);
	LCD_DrawFilledCircle(x, y, 4, show ? WHITE : bk_color);
}
