//------------------------------------------------------------------
void LCD_ShowPicture_Fast(u16 x, u16 y, u16 length, u16 width, const u8 *pic)//[])
{
u32 k = 0;

	LCD_Address_Set(x, y, x + length - 1, y + width - 1);

	LCD_CS_Clr();


	for (u16 i = 0; i < length; i++) {
		for (u16 j = 0; j < width; j++) {
			LCD_WR_DATAS((u8 *)(pic + k), 2);
			k += 2;	
            /*while(SPI_I2S_GetFlagStatus(portLCD, SPI_I2S_FLAG_TXE) == RESET);
            SPI_I2S_SendData(portLCD, pic[k << 1]);
            while(SPI_I2S_GetFlagStatus(portLCD, SPI_I2S_FLAG_TXE) == RESET);
            SPI_I2S_SendData(portLCD, pic[(k << 1) + 1]);
			k++;
			*/
		}
	}

	LCD_CS_Set();
}
#else
	const uint8_t *gImage_test = NULL;
#endif
//------------------------------------------------------------------
#if defined(SET_FMRAM) // && defined(SET_BIG_PIC) 
void LCD_ShowPicture_FMRAM(u16 x, u16 y, u16 length, u16 width)
{
uint16_t len = width << 1;

	if (!blk_mem) blk_mem = (uint8_t *)calloc(1, len);
	if (blk_mem) { 
		uint32_t addr = blk_addr;
		LCD_Address_Set(x, y, x + length - 1, y + width - 1);
		LCD_CS_Clr();
		for (uint16_t i = 0; i < length; i++) {
			uint32_t ofs = 0;
//#ifdef SET_DMA_FMRAM
//			DMA_Rx_Init(DMA1_Channel2, (uint32_t)&portFMRAM->DATAR, (uint32_t)blk_mem, len);
//			DMA_ClearFlag(DMA1_FLAG_TC2);
//			DMA_Cmd(DMA1_Channel2, ENABLE);
//    		while(!DMA_GetFlagStatus(DMA1_FLAG_TC2));
//#else			
			SPI_Flash_Read(blk_mem, addr, len);//get data from FMRAM (width << 1)
//#endif
			for (uint16_t j = 0; j < width; j++) {
				LCD_WR_DATAS((u8 *)(blk_mem + ofs), 2);
				ofs += 2;
			}
			addr += len;
		}
		LCD_CS_Set();

		free(blk_mem);
		blk_mem = NULL;
	}
}
#endif
//------------------------------------------------------------------
int lcd_init()
{
	lcd_gpio_init();
	Delay_MS(10);
	LCD_RES_Set();
	Delay_MS(10);
	LCD_BLK_Set();
    Delay_MS(10);
	
	//************* Start Initial Sequence **********
	LCD_WR_REG(0x11); //Sleep out 
	Delay_MS(120);    //Delay 120ms 
	//************* Start Initial Sequence **********

	LCD_WR_REG(0x36);
	if (USE_HORIZONTAL == 0) {
		LCD_WR_DATA8(0x00);
	} else if (USE_HORIZONTAL == 1) {
		LCD_WR_DATA8(0xC0);
	} else if (USE_HORIZONTAL == 2) {
		LCD_WR_DATA8(0x70);
	} else {
		LCD_WR_DATA8(0xA0);
	}
	LCD_WR_REG(0x3A);			
	LCD_WR_DATA8(0x05);

	LCD_WR_REG(0xB2);			
	{
		u8 dan[] = {0x0C, 0x0C, 0x00, 0x33, 0x33}; 	
		LCD_WR_DATAS(dan, sizeof(dan));
	}		

	LCD_WR_REG(0xB7);			
	LCD_WR_DATA8(0x35);

	LCD_WR_REG(0xBB);			
	LCD_WR_DATA8(0x32); //Vcom=1.35V
					
	LCD_WR_REG(0xC2);
	LCD_WR_DATA8(0x01);

	LCD_WR_REG(0xC3);			
	LCD_WR_DATA8(0x15); //GVDD=4.8V  ÑÕÉ«Éî¶È
				
	LCD_WR_REG(0xC4);			
	LCD_WR_DATA8(0x20); //VDV, 0x20:0v

	LCD_WR_REG(0xC6);			
	LCD_WR_DATA8(0x0F); //0x0F:60Hz        	

	LCD_WR_REG(0xD0);			
	LCD_WR_DATA8(0xA4);
	LCD_WR_DATA8(0xA1); 

	LCD_WR_REG(0xE0);
	{
		u8 dan[] = {0xD0, 0x08, 0x0E, 0x09, 0x09, 0x05, 0x31, 0x33, 0x48, 0x17, 0x14, 0x15, 0x31, 0x34};	
		LCD_WR_DATAS(dan, sizeof(dan));
	}   

	LCD_WR_REG(0xE1);     
	{
		u8 dan[] = {0xD0, 0x08, 0x0E, 0x09, 0x09, 0x15, 0x31, 0x33, 0x48, 0x17, 0x14, 0x15, 0x31, 0x34};	
		LCD_WR_DATAS(dan, sizeof(dan));
	}

	LCD_WR_REG(0x21); 
	LCD_WR_REG(0x29);

    u16 Ms = 0;
	for (u8 i = 0; i < sizeof(all_color) >> 1; i++) {
    	LCD_Fill_Fast(0, 0, LCD_W, LCD_H, all_color[i]);
		if (all_color[i] == WHITE)
			Ms = 1;
		else
			Ms = 125;
		Delay_MS(Ms);
    }
    
    return 0;
}
//
void LCD_OFF()
{
	LCD_WR_REG(0x28);
}
